//===- fused_rmsnorm_matmul.cu - PolyKernel fused kernel --------*- CUDA -*-===//
//
// AUTO-GENERATED by `polykernel-opt --lower-to-cuda` (Todo 14 / Wave 3).
// Do not edit by hand; re-run the pass to regenerate.
//
// Fused RMSNorm + MatMul (PROLOGUE fusion): out[M,N] = matmul(rmsnorm(x, eps), w).
// RMSNorm over x's last axis (the matmul contraction K) is folded into the tiled
// GEMM's A-operand load: for each output row the RMS of the input row is reduced
// first (warp-shuffle reduction over K), then x is normalized on the fly and staged
// into shared memory as the matmul's A tile — so the normalized tensor is never
// materialized in global memory. Matches tests/golden/golden.py:
//     fused_rmsnorm_matmul(x, w, eps) = matmul(rmsnorm(x, None, eps), w).
//
// ROUNDING CONTRACT (matches golden): the RMS reduction + the fp32 matmul
// accumulation are fp32; each normalized A element is rounded to bf16 as it is
// staged (== golden's rmsnorm bf16 output that the matmul then reads); the fp32
// accumulator is rounded back to bf16 (RNE) on store. Bounds checks handle M/N/K
// that are not tile multiples. Written against the portable template
// (kernels/template/kernel_common.h) so it compiles UNCHANGED under
// `nvcc -DPOLYKERNEL_CUDA` and `hipcc -DPOLYKERNEL_HIP`.
//
//===----------------------------------------------------------------------===//

#include "../template/kernel_common.h"

namespace {

// Output tile per block + K-tile width (mirrors matmul.cu). One thread (tx, ty)
// computes one output element out[row, col]; blockDim == (kBlockN, kBlockM) ==
// 16 x 16 == 256 threads. gridDim.x tiles N (columns), gridDim.y tiles M (rows).
constexpr int kBlockM = 16;
constexpr int kBlockN = 16;
constexpr int kBlockK = 16;

// Per-row sum-of-squares reduction over K. The 16 threads of a row (same ty,
// tx = 0..15) occupy a contiguous 16-lane group within a warp (linear id =
// ty*16 + tx, so each row maps to a 16-lane half-warp); a butterfly over offsets
// {8,4,2,1} therefore reduces each row independently and lands the total in every
// lane of that row. The reduction width (kBlockN == 16) is <= PK_WARP_SIZE, so it
// completes within a warp — no shared-memory block-reduction stage is needed
// (unlike rmsnorm.cu, where 256 threads reduce ONE row across 8 warps).
PK_DEVICE_INLINE float row_reduce_sum(float v) {
#pragma unroll
  for (int offset = kBlockN / 2; offset > 0; offset >>= 1)
    v += pk_shfl_xor_sync(v, offset);
  return v;
}

PK_GLOBAL void fused_rmsnorm_matmul_kernel(const pk_bf16 *__restrict__ X,
                                           const pk_bf16 *__restrict__ W,
                                           pk_bf16 *__restrict__ C, int M, int N,
                                           int K, float epsilon) {
  PK_SHARED pk_bf16 As[kBlockM][kBlockK];
  PK_SHARED pk_bf16 Bs[kBlockK][kBlockN];

  const int tx = threadIdx.x; // column within the output tile [0, kBlockN)
  const int ty = threadIdx.y; // row within the output tile    [0, kBlockM)
  const int row = blockIdx.y * kBlockM + ty;
  const int col = blockIdx.x * kBlockN + tx;

  // Prologue: RMS of this output row's input row, reduced over K (the rmsnorm
  // axis == x's last axis). fp32 sum of squares; bf16 input upcast exactly.
  float local_ss = 0.0f;
  if (row < M) {
    const pk_bf16 *xrow = X + static_cast<size_t>(row) * K;
    for (int k = tx; k < K; k += kBlockN) {
      float v = pk_bf162float(xrow[k]);
      local_ss += v * v;
    }
  }
  float ss = row_reduce_sum(local_ss);
  // rms = sqrt(mean(x^2) + epsilon), fp32 (matches golden np.sqrt(np.mean+eps)).
  float rms = sqrtf(ss / static_cast<float>(K) + epsilon);

  // Tiled GEMM with the normalized A operand (prologue fusion): each staged A
  // element is x/rms rounded to bf16 (== golden's rmsnorm bf16 output the matmul
  // reads). Out-of-bounds loads (non-tile-multiple M/N/K) read as 0 so they never
  // contribute to the accumulator.
  float acc = 0.0f;
  const int numKTiles = (K + kBlockK - 1) / kBlockK;
  for (int t = 0; t < numKTiles; ++t) {
    int aCol = t * kBlockK + tx;
    if (row < M && aCol < K) {
      float a = pk_bf162float(X[static_cast<size_t>(row) * K + aCol]) / rms;
      As[ty][tx] = pk_float2bf16(a); // round normalized A to bf16 (golden contract)
    } else {
      As[ty][tx] = pk_float2bf16(0.0f);
    }
    int bRow = t * kBlockK + ty;
    Bs[ty][tx] = (bRow < K && col < N) ? W[static_cast<size_t>(bRow) * N + col]
                                       : pk_float2bf16(0.0f);
    pk_syncthreads();

    // Accumulate this K-tile in fp32 (bf16 upcast exactly on each read).
#pragma unroll
    for (int kk = 0; kk < kBlockK; ++kk)
      acc += pk_bf162float(As[ty][kk]) * pk_bf162float(Bs[kk][tx]);
    pk_syncthreads();
  }

  // Round the fp32 accumulator back to bf16 (RNE) and store, within bounds.
  if (row < M && col < N)
    C[static_cast<size_t>(row) * N + col] = pk_float2bf16(acc);
}

} // namespace

// Host-callable launch entry (the launch_*-style ABI). out[M,N] =
// matmul(rmsnorm(input, eps), weight); input is [M,K] (batched leading dims
// flattened into M by the caller), weight is [K,N]. `weight` is the MATMUL weight
// (the rmsnorm has no per-feature scale here, matching golden fused_rmsnorm_matmul
// with weight=None). The stream is passed as void* to keep the signature
// backend-agnostic and cast to the backend stream type (pk_stream_t) inside.
void launch_fused_rmsnorm_matmul(const pk_bf16 *input, const pk_bf16 *weight,
                                 pk_bf16 *output, int M, int N, int K,
                                 float epsilon, void *stream) {
  dim3 block(kBlockN, kBlockM);
  dim3 grid((N + kBlockN - 1) / kBlockN, (M + kBlockM - 1) / kBlockM);
  pk_stream_t s = static_cast<pk_stream_t>(stream);
  PK_LAUNCH(fused_rmsnorm_matmul_kernel, grid, block, 0, s, input, weight, output,
            M, N, K, epsilon);
  PK_CHECK(pk_get_last_error());
}
